function modelRow(path,pred){return D.ml_model_comparison_v74?.find(x=>String(x.pathway).toLowerCase()===String(path).toLowerCase()&&x.predictor_set===pred)}

function oofDiagnostics(path,threshold){
 const col={Methanogenesis:'ML_methanogenesis_environment_only_OOF_probability_v74','Sulfate reduction':'ML_sulfate_reduction_environment_only_OOF_probability_v74','Sulfur reduction':'ML_sulfur_reduction_environment_only_OOF_probability_v74','Iron reduction':'ML_iron_reduction_environment_only_OOF_probability_v74','Fermentation':'ML_fermentation_environment_only_OOF_probability_v74','Hydrogen oxidation':'ML_hydrogen_oxidation_environment_only_OOF_probability_v74'}[path];
 const map=new Map((D.ml_environment_oof_v74||[]).map(x=>[String(x.record_id),Number(x[col])]));
 const rows=D.records.map(r=>{const prob=map.get(String(r.record_id));if(!Number.isFinite(prob))return null;return {y:hasPath(r,path)?1:0,p:prob}}).filter(Boolean);
 const positives=rows.filter(x=>x.y===1).length, negatives=rows.length-positives;
 const sorted=rows.slice().sort((a,b)=>b.p-a.p);
 const rocX=[0],rocY=[0],prX=[0],prY=[positives?positives/rows.length:0];
 let tp=0,fp=0,last=null;
 sorted.forEach((r,i)=>{if(last!==null&&r.p!==last){rocX.push(negatives?fp/negatives:0);rocY.push(positives?tp/positives:0);prX.push(positives?tp/positives:0);prY.push((tp+fp)?tp/(tp+fp):1)};r.y?tp++:fp++;last=r.p;if(i===sorted.length-1){rocX.push(negatives?fp/negatives:0);rocY.push(positives?tp/positives:0);prX.push(positives?tp/positives:0);prY.push((tp+fp)?tp/(tp+fp):1)}});
 const cm={tp:0,fp:0,tn:0,fn:0};rows.forEach(r=>{const pred=r.p>=threshold?1:0;if(pred&&r.y)cm.tp++;else if(pred&&!r.y)cm.fp++;else if(!pred&&!r.y)cm.tn++;else cm.fn++});
 const precision=cm.tp+cm.fp?cm.tp/(cm.tp+cm.fp):0,recall=cm.tp+cm.fn?cm.tp/(cm.tp+cm.fn):0,specificity=cm.tn+cm.fp?cm.tn/(cm.tn+cm.fp):0,balanced=(recall+specificity)/2;
 return {rows,rocX,rocY,prX,prY,cm,precision,recall,specificity,balanced,positives,negatives};
}
function renderML(){
 const paths=D.ml_random.map(x=>x.pathway);if($('#mlPathway')&&!$('#mlPathway').dataset.ready){paths.forEach(p=>$('#mlPathway').insertAdjacentHTML('beforeend',`<option value="${esc(p)}">${esc(prettyPath(p))}</option>`));$('#mlPathway').dataset.ready='1'}const p=$('#mlPathway')?.value||paths[0];const pDisplay=prettyPath(p),val=$('#mlValidation')?.value||'random';let pred=$('#mlPredictors')?.value||'environment';if(val==='grouped'){pred='environment';if($('#mlPredictors')){$('#mlPredictors').value='environment';$('#mlPredictors').disabled=true}}else if($('#mlPredictors'))$('#mlPredictors').disabled=false;const random=modelRow(p,pred==='combined'?'environment_plus_taxonomy':pred==='taxonomy'?'taxonomy_only':'environment_only');const group=D.ml_grouped_validation_v74?.find(x=>String(x.pathway).toLowerCase()===String(p).toLowerCase())||D.ml_grouped.find(x=>x.pathway===p);let score=null,label='',note='';if(val==='random'){score=random?.ROC_AUC??null;label='random 5-fold ROC-AUC';note='Stored final v74 model-comparison result.'}else{score=group?.grouped_ROC_AUC??group?.roc??null;label='phylum-grouped environment-only ROC-AUC';note=group?.note||'Grouped validation is only available for environment-only models in this release.'}
 const finite=v=>Number.isFinite(Number(v));set('mlInputSummary',pred==='environment'?'environmental predictors':pred==='taxonomy'?'taxonomic predictors':'environment + taxonomy');set('mlModelSummary',val==='random'?'5-fold shuffled CV':'phylum-grouped environment-only holdout');set('mlScore',finite(score)?Number(score).toFixed(3):'Not estimable');set('mlScoreLabel',label||'validation status');
 const metrics=val==='grouped'?[group?.grouped_ROC_AUC,group?.grouped_PR_AUC,group?.grouped_balanced_accuracy]:[random?.ROC_AUC,random?.PR_AUC,random?.balanced_accuracy];const labels=['ROC-AUC','PR-AUC','Balanced accuracy'];if(metrics.some(v=>!finite(v)))noData('mlPerformance','Grouped validation not estimable',`The selected pathway does not have a valid phylum-grouped metric for this release. This is an evidence limitation, not a zero score.`);else plot('mlPerformance',[{x:labels,y:metrics,type:'bar',text:metrics.map(v=>Number(v).toFixed(3)),textposition:'outside',hovertemplate:'%{x}<br>%{y:.3f}<extra></extra>'}],{yaxis:{range:[0,1],title:'Score'}},'<b>How to read</b><p>Compare the three metrics together. ROC-AUC and PR-AUC are ranking metrics; balanced accuracy summarizes sensitivity and specificity.</p>');
 const compPred=[['environment_only','Environment only'],['taxonomy_only','Taxonomy only'],['environment_plus_taxonomy','Environment + taxonomy']].map(([key,label])=>({key,label,row:modelRow(p,key)}));plot('mlComparison',[{x:compPred.map(x=>x.label),y:compPred.map(x=>x.row?.ROC_AUC??null),type:'bar',text:compPred.map(x=>x.row?.ROC_AUC==null?'NE':Number(x.row.ROC_AUC).toFixed(3)),textposition:'outside',hovertemplate:'%{x}<br>ROC-AUC %{y:.3f}<extra></extra>'}],{yaxis:{range:[0,1],title:'ROC-AUC'},margin:{l:60,r:20,t:45,b:75}},'<b>How to read</b><p>Each bar is a separately validated predictor set for the selected pathway. Compare environment-only with taxonomy-only before interpreting combined performance.</p>');
 const rs=modelRow(p,'environment_only')?.ROC_AUC,gs=group?.grouped_ROC_AUC??group?.roc;if(finite(rs)&&finite(gs))plot('mlStress',[{x:['Random environment','Phylum-grouped environment'],y:[rs,gs],type:'bar',text:[rs,gs].map(v=>Number(v).toFixed(3)),textposition:'outside',hovertemplate:'%{x}<br>%{y:.3f}<extra></extra>'}],{yaxis:{range:[0,1],title:'ROC-AUC'}},'<b>How to read</b><p>This is the main robustness test. A large drop after phylum holdout indicates that random-CV performance partly tracked lineage structure.</p>');else noData('mlStress','Lineage-controlled result not estimable','The selected pathway does not have a valid grouped ROC-AUC in this release. Methanogenesis is the key example: all positives are concentrated in one phylum group, so a lineage-independent estimate is not defensible.');
 const ex=D.extreme;plot('mlExtreme',[{x:['ROC-AUC','PR-AUC','Balanced accuracy'],y:[ex.roc_auc,ex.pr_auc,ex.balanced_accuracy],type:'bar',text:[ex.roc_auc,ex.pr_auc,ex.balanced_accuracy].map(v=>v.toFixed(3)),textposition:'outside',hovertemplate:'%{x}<br>%{y:.3f}<extra></extra>'}],{yaxis:{range:[0,1]}},'<b>How to read</b><p>This classifier targets Topt ≥80 °C. It excludes Tmin/Topt/Tmax from predictors, so it is not simply predicting the label from the label itself.</p>');
 const threshold=Number($('#mlThreshold')?.value||0.5);if($('#mlThresholdValue'))$('#mlThresholdValue').textContent=threshold.toFixed(2);if($('#mlThresholdLabel'))$('#mlThresholdLabel').textContent=`threshold ${threshold.toFixed(2)}`;const od=oofDiagnostics(p,threshold);plot('mlCurves',[{x:od.rocX,y:od.rocY,type:'scatter',mode:'lines',name:'ROC',hovertemplate:'FPR %{x:.3f}<br>TPR %{y:.3f}<extra></extra>'},{x:[0,1],y:[0,1],type:'scatter',mode:'lines',name:'chance',line:{dash:'dot'}}],{xaxis:{title:'False positive rate',range:[0,1]},yaxis:{title:'True positive rate',range:[0,1]}},'<b>How to read</b><p>The curve is built from the stored out-of-fold environment-only probabilities. Moving the threshold is not needed for ROC; every threshold contributes a point.</p>');plot('mlPR',[{x:od.prX,y:od.prY,type:'scatter',mode:'lines',name:'PR',hovertemplate:'Recall %{x:.3f}<br>Precision %{y:.3f}<extra></extra>'},{x:[0,1],y:[od.positives/(od.positives+od.negatives),od.positives/(od.positives+od.negatives)],type:'scatter',mode:'lines',name:'prevalence baseline',line:{dash:'dot'}}],{xaxis:{title:'Recall',range:[0,1]},yaxis:{title:'Precision',range:[0,1]}},'<b>How to read</b><p>The curve is built from stored out-of-fold environment-only probabilities. The dotted line is the positive-class prevalence baseline.</p>');plot('mlConfusion',[{z:[[od.cm.tn,od.cm.fp],[od.cm.fn,od.cm.tp]],x:['Predicted negative','Predicted positive'],y:['Actual negative','Actual positive'],type:'heatmap',colorscale:'Greens',text:[[od.cm.tn,od.cm.fp],[od.cm.fn,od.cm.tp]],texttemplate:'%{text}',hovertemplate:'%{y} → %{x}<br>%{z} records<extra></extra>'}],{margin:{l:115,r:20,t:45,b:70}},'<b>How to read</b><p>The threshold turns the continuous OOF probability into a binary decision. Change the threshold on the left and watch false positives/negatives move.</p>');set('mlThresholdDetail',`<b>Threshold ${threshold.toFixed(2)}</b> · precision ${od.precision.toFixed(3)} · recall ${od.recall.toFixed(3)} · specificity ${od.specificity.toFixed(3)} · balanced accuracy ${od.balanced.toFixed(3)}. These are diagnostics on out-of-fold terrestrial predictions, not life probabilities.`);
 set('mlInterpretation',`<b>${esc(prettyPath(p))} · ${esc(label)}</b><p>${esc(note)}</p><p><b>Scientific reading:</b> the stored metric describes how well the model ranks known terrestrial records. It is not an extraterrestrial life detector.</p>`);set('mlMethodology',`<div class="method-grid"><div><b>1 · Target</b><p>Curated metabolic capability: ${esc(p)}.</p></div><div><b>2 · Predictors</b><p>${esc(pred==='environment'?'Environmental / physiological descriptors':pred==='taxonomy'?'Taxonomic context':'Environmental + taxonomic context')}.</p></div><div><b>3 · Leakage control</b><p>Tmin, Topt and Tmax are excluded from the primary metabolic predictors; target/pathway text is excluded. Missing values are handled inside the model pipeline and categorical variables are encoded within it.</p></div><div><b>4 · Validation</b><p>${val==='random'?'Five shuffled folds estimate ordinary generalization.':'Whole phylum groups are held out to test whether environmental signal travels beyond the lineages represented in training.'}</p></div><div><b>5 · Interpretation</b><p>${group?.note||'Compare environment-only against taxonomy-only and combined benchmarks before attributing performance to environmental constraints.'}</p></div></div>`);
 set('mlReasoningPanel',`<div class="method-grid"><div><b>Question</b><p>Can the selected target be distinguished from non-target records?</p></div><div><b>Evidence entering model</b><p>${esc(pred==='environment'?'environmental predictors':pred==='taxonomy'?'taxonomic context':'environment + taxonomic context')}</p></div><div><b>Validation logic</b><p>${esc(val==='random'?'Random 5-fold estimates ordinary held-out performance.':'Phylum grouping asks whether environmental signal transfers beyond the training lineages.')}</p></div><div><b>Observed output</b><p>${score==null?'Not estimable':Number(score).toFixed(3)} ${esc(label)}</p></div><div><b>Interpretation</b><p>${esc(group?.note||'Compare predictor sets and lineage-controlled results before assigning a causal environmental interpretation.')}</p></div></div>`);runMLScenario();
}
function runMLScenario(){if(!D)return;const p=$('#mlPathway')?.value||'Methanogenesis';const t=num($('#mlTemp')?.value),ph=num($('#mlPH')?.value),sal=num($('#mlSal')?.value),press=num($('#mlPressure')?.value),dom=$('#mlDomain')?.value||'',env=$('#mlEnvironment')?.value||'',oxy=$('#mlOxygen')?.value||'';const hasScenario=[t,ph,sal,press,dom,env,oxy].some(v=>v!==null&&v!=='');if(!hasScenario){set('mlScenarioResult','<div class="scenario-placeholder"><b>Add one or more scenario values.</b><p>The explorer will locate the closest measured ThermoBase records and show their stored out-of-fold environment-only probabilities for the selected pathway.</p></div>');return}const candidates=D.records.map(r=>{if(dom&&r.domain!==dom)return null;if(env&&r.environment!==env)return null;if(oxy&&r.oxygen_requirement!==oxy)return null;let s=0,n=0;const dims={};[[t,num(r.avg_optimum_temp_c),45,'temperature'],[ph,num(r.avg_optimum_ph),3,'pH'],[sal,num(r.avg_opt_salinity_percent_normalized_v40),10,'salinity'],[press,num(r.optimum_pressure_mpa),50,'pressure']].forEach(([q,v,scale,k])=>{if(q!=null&&v!=null){dims[k]=Math.max(0,1-Math.abs(q-v)/scale);s+=dims[k];n++}});if(!n)return null;return {r,dist:s/n,dims}}).filter(Boolean).sort((a,b)=>b.dist-a.dist).slice(0,12);const col={Methanogenesis:'ML_methanogenesis_environment_only_OOF_probability_v74','Sulfate reduction':'ML_sulfate_reduction_environment_only_OOF_probability_v74','Sulfur reduction':'ML_sulfur_reduction_environment_only_OOF_probability_v74','Iron reduction':'ML_iron_reduction_environment_only_OOF_probability_v74','Fermentation':'ML_fermentation_environment_only_OOF_probability_v74','Hydrogen oxidation':'ML_hydrogen_oxidation_environment_only_OOF_probability_v74'}[p];const byId=new Map((D.ml_environment_oof_v74||[]).map(x=>[String(x.record_id),x[col]]));const rows=candidates.map(x=>({...x,prob:byId.get(String(x.r.record_id))})).filter(x=>x.prob!=null);const best=rows[0];const reasoning=best?Object.entries(best.dims).map(([k,v])=>`<span><b>${esc(k)}</b> ${v.toFixed(2)}</span>`).join(' · '):'';set('mlScenarioResult',rows.length?`<div class="scenario-head"><b>Closest measured analogues</b><span>${rows.length} records with stored out-of-fold ${esc(p)} probabilities</span></div><div class="scenario-reasoning"><b>Why the closest record is close</b><span>${reasoning}</span></div><div class="scenario-table">${rows.map(x=>`<button class="scenario-row" data-record="${esc(x.r.record_id)}"><span><b>${esc(x.r.name)}</b><small>${esc(x.r.environment||'—')} · Topt ${x.r.avg_optimum_temp_c??'—'}°C · pH ${x.r.avg_optimum_ph??'—'}</small></span><strong>${Number(x.prob).toFixed(3)}</strong></button>`).join('')}</div><div class="scenario-foot">These are <b>out-of-fold probabilities for measured records</b>, not a prediction for your new environment. They show how the validated environment-only model behaves around analogous observations.</div>`:'<div class="scenario-placeholder"><b>No comparable measured records with stored OOF probabilities.</b><p>Relax the scenario constraints or remove one of the sparse variables.</p></div>')}
function renderSandbox(){runSandbox()}
function runSandbox(){if(!D)return;const t=num($('#sbTemp')?.value)??70,ph=num($('#sbPH')?.value)??8,sal=num($('#sbSal')?.value)??1,press=num($('#sbPressure')?.value)??0.1,o2=$('#sbO2')?.value||'anoxic',h2=$('#sbH2')?.value||'high',co2=$('#sbCO2')?.value||'high',sulf=$('#sbSulfate')?.value||'unknown',sulfur=$('#sbSulfur')?.value||'unknown',iron=$('#sbIron')?.value||'unknown';const rs=D.records.map(r=>{const rt=num(r.avg_optimum_temp_c),rp=num(r.avg_optimum_ph),rsal=num(r.avg_opt_salinity_percent_normalized_v40),rpr=num(r.optimum_pressure_mpa);if(rt==null||rp==null)return null;let s=0,n=0;[[t,rt,45],[ph,rp,3],[sal,rsal,10],[press,rpr,50]].forEach(([q,v,scale])=>{if(v!=null){s+=Math.max(0,1-Math.abs(v-q)/scale);n++}});if(o2==='anoxic'&&/anaerob|strict|anoxic|oxygen-free/i.test(String(r.oxygen_requirement||'')))s+=.3;if(o2==='oxic'&&/aerob/i.test(String(r.oxygen_requirement||'')))s+=.3;return {...r,compat:n?s/n:0}}).filter(Boolean).sort((a,b)=>b.compat-a.compat);const top=rs.slice(0,20);const ps=['Methanogenesis','Sulfate reduction','Sulfur reduction','Iron reduction','Fermentation','Hydrogen oxidation'];const chemFactor=(p)=>{let f=0;if(p==='Methanogenesis'){if(o2==='anoxic')f+=.35;if(h2==='high')f+=.35;else if(h2==='moderate')f+=.18;if(co2==='high')f+=.30;else if(co2==='moderate')f+=.15}if(p==='Sulfate reduction'){if(o2!=='oxic')f+=.25;if(sulf==='high')f+=.45;else if(sulf==='moderate')f+=.22;if(h2==='high')f+=.20;else if(h2==='moderate')f+=.10}if(p==='Sulfur reduction'){if(o2!=='oxic')f+=.25;if(sulfur==='high')f+=.45;else if(sulfur==='moderate')f+=.22;if(h2==='high')f+=.20;else if(h2==='moderate')f+=.10}if(p==='Iron reduction'){if(o2!=='oxic')f+=.25;if(iron==='high')f+=.45;else if(iron==='moderate')f+=.22;if(h2==='high')f+=.20;else if(h2==='moderate')f+=.10}if(p==='Fermentation'){if(o2!=='oxic')f+=.35;if(co2==='high'||co2==='moderate')f+=.10}if(p==='Hydrogen oxidation'){if(o2==='oxic')f+=.45;if(h2==='high')f+=.35;else if(h2==='moderate')f+=.18}return 1+f};const pathwayScores=Object.fromEntries(ps.map(p=>[p,Math.round(top.filter(r=>hasPath(r,p)).length*chemFactor(p))]));const gases=[['CH₄','Methanogenesis'],['H₂S / sulfide','Sulfate reduction'],['H₂S / sulfide','Sulfur reduction'],['Fe(II) / reduced iron','Iron reduction'],['reduced fermentation products','Fermentation'],['oxidized H₂ / water','Hydrogen oxidation']].map(([g,p])=>[g,pathwayScores[p]]);set('sandboxKpis',[[top.length,'closest measured analogues'],[fmt(median(top.map(r=>r.avg_optimum_temp_c)),1)+' °C','median analogue Topt'],[fmt(median(top.map(r=>r.avg_optimum_ph)),1),'median analogue pH'],[Object.entries(pathwayScores).sort((a,b)=>b[1]-a[1])[0]?.[0]||'—','leading scenario pathway']].map(x=>`<div><b>${esc(x[0])}</b><span>${esc(x[1])}</span></div>`).join(''));plot('sandboxPathways',[{x:ps.map(p=>p),y:ps.map(p=>pathwayScores[p]),type:'bar',orientation:'h',text:ps.map(p=>pathwayScores[p]),textposition:'outside',hovertemplate:'%{y}<br>scenario score %{x}<extra></extra>'}],{xaxis:{title:'Scenario compatibility score (heuristic)',range:[0,Math.max(2,...ps.map(p=>pathwayScores[p])+2)]},margin:{l:185,r:35,t:45,b:45}},'<b>How to read</b><p>Compare the six pathway scores under the current scenario. The score is a transparent heuristic combining measured-analogue support with selected chemical and oxygen constraints; it is not a calibrated probability.</p>');if(top.length)plot('sandboxPlot',[{x:top.map(r=>r.avg_optimum_temp_c),y:top.map(r=>r.avg_optimum_ph),mode:'markers',type:'scatter',text:top.map(r=>r.name),marker:{size:9,color:top.map(r=>r.compat),colorscale:'Viridis',showscale:true,colorbar:{title:'compat.'}},hovertemplate:'<b>%{text}</b><br>Topt %{x}°C · pH %{y}<br>analogue compatibility %{marker.color:.2f}<extra></extra>'},{x:[t],y:[ph],mode:'markers',type:'scatter',marker:{size:15,symbol:'x'},name:'Your environment'}],{xaxis:{title:'Topt °C'},yaxis:{title:'pHopt'}},'<b>How to read</b><p>Colored points are measured analogues; the X is the constructed environment. Compatibility is a normalized similarity heuristic, not a probability.</p>');else noData('sandboxPlot','Scenario analogue map','No measured records match the minimum temperature/pH requirements.');plot('sandboxProducts',[{x:gases.map(x=>x[1]),y:gases.map(x=>x[0]),type:'bar',orientation:'h',text:gases.map(x=>x[1]),textposition:'outside',hovertemplate:'%{y}<br>%{x} close analogues<extra></extra>'}],{xaxis:{title:'Closest analogues carrying pathway'}},'<b>How to read</b><p>All primary pathway counts remain visible, including zero. Candidate products are pathway hypotheses, not atmospheric abundance predictions.</p>');set('sandboxText',`<b>Scenario:</b> ${t}°C · pH ${ph} · ${sal}% salinity · ${press} MPa · ${o2} · H₂ ${h2} · CO₂ ${co2} · sulfate ${sulf} · sulfur ${sulfur} · Fe(III) ${iron}. <p>The analogue ranking is based on measured physiological distance plus a qualitative oxygen adjustment; the pathway/product ranking additionally responds to the selected H₂, CO₂, sulfate, sulfur and Fe(III) availability. This is a transparent scenario heuristic and does not retrain the ML models and cannot yield a defensible probability of life or abiotic origin.</p>`);set('sandboxEvidence',`<div class="evidence-stack"><b>What this scenario can say</b><p>Which characterized ThermoBase organisms occupy similar measured space and which pathways are represented among those analogues.</p><b>What it cannot say</b><p>It cannot calculate a percentage probability of life, biological methane or abiotic methane from the current evidence layer.</p><b>Why</b><p>A defensible probability would require an explicit validated probabilistic model plus planetary chemical priors and abiotic production models.</p></div>`)}
function worldData(){return {enceladus:{title:'Enceladus',kind:'Ocean world · plume-accessible',stance:'The strongest ThermoBase case study because ocean-derived material is sampled by plumes and molecular H₂ has been detected.',observed:['Molecular H₂ in plume material; evidence consistent with water–rock chemistry','Plume sampling provides unusually direct access to ocean-derived material'],thermo:'ThermoBase supplies terrestrial metabolic analogues, especially hydrogenotrophic methanogenesis, and tests how environmental constraints align with those analogues.',unknown:['Exact ocean temperature, pressure and activities','Abiotic methane production and transport contributions'],discriminate:['Better constraints on abiotic methane and ocean chemistry','Measurements that distinguish biological production from water–rock/thermal chemistry'],score:'Case study'},europa:{title:'Europa',kind:'Ocean world · remote subsurface',stance:'A major ocean-world target, but its evidence regime is different from Enceladus because persistent plume sampling is not available in the same way.',observed:['Subsurface ocean and chemically active surface environment are central mission targets','2026 NASA reporting identifies ammonia-bearing compounds in reanalysis of Galileo data'],thermo:'ThermoBase provides terrestrial environment–metabolism analogues that can organize candidate redox processes.',unknown:['Ocean chemistry and energy flux at biologically relevant depths','How surface chemistry connects quantitatively to the ocean'],discriminate:['Europa Clipper measurements of composition, geology and possible exchange processes'],score:'Analogue'},trappist:{title:'TRAPPIST-1 e',kind:'Habitable-zone exoplanet · remote atmosphere',stance:'This is an atmospheric inference problem: the biological environment is not sampled directly.',observed:['Earth-sized habitable-zone target','Webb observations constrain some atmospheric scenarios but do not provide a definitive biosphere diagnosis'],thermo:'ThermoBase can act as a terrestrial process library for candidate gases and metabolic niches under specified environments.',unknown:['Atmospheric composition and surface conditions','Stellar activity and photochemical pathways'],discriminate:['Repeated spectroscopy and better atmospheric retrieval constraints'],score:'Remote target'},k218:{title:'K2-18 b',kind:'Sub-Neptune · atmospheric chemistry',stance:'Methane and carbon dioxide are scientifically interesting, but atmospheric molecules are not automatically biological.',observed:['JWST observations report methane and carbon dioxide','Possible DMS evidence remains a model-dependent question requiring further scrutiny'],thermo:'ThermoBase can organize terrestrial chemical transformations that produce candidate molecules, but cannot substitute for planetary photochemical/abiotic models.',unknown:['Planetary atmosphere/ocean structure','Abiotic production pathways and transport'],discriminate:['Independent atmospheric constraints and stronger abiotic baseline models'],score:'Remote target'},earth:{title:'Earth benchmark',kind:'Known biosphere · reference',stance:'Earth is the only world here with an independently known biosphere and supplies the biological calibration domain.',observed:['Known life','Extensive experimental and environmental measurements'],thermo:'Earth provides the training and validation domain for the environment–metabolism framework.',unknown:['Not a life-detection unknown; remaining uncertainty concerns extrapolation beyond Earth'],discriminate:['Independent datasets and planetary analogues test generalization'],score:'Known life'}}}
function renderWorld(w){const x=worldData()[w];set('worldContent',`<div class="world-card"><div><span class="tag">${esc(x.kind)}</span><h3>${esc(x.title)}</h3><p>${esc(x.stance)}</p><div class="world-four"><div><b>OBSERVED / CONSTRAINED</b><ul>${x.observed.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div><div><b>THERMOBASE CONTRIBUTION</b><p>${esc(x.thermo)}</p></div><div><b>WHAT REMAINS UNKNOWN</b><ul>${x.unknown.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div><div><b>WHAT WOULD DISCRIMINATE</b><ul>${x.discriminate.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div></div></div><div class="world-score"><strong>${esc(x.score)}</strong><small>framework role — not a life probability</small></div></div>`);set('worldSources',D.web_release?.planetary_sources?.[x.title]?.length?`<b>Current references</b>${D.web_release.planetary_sources[x.title].map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)} ↗</a>`).join('')}`:'<b>Reference</b><span>Earth is the known-life calibration benchmark.</span>');
 const title=$('#worldPathwayTitle'),sub=$('#worldPathwaySubtitle');
 if(title)title.textContent=w==='enceladus'?'Enceladus pathway discrimination':'Why this pathway matrix is not applied here';
 if(sub)sub.textContent=w==='enceladus'?'14 criteria · ordinal compatibility':'Enceladus-specific framework';
 if(w==='enceladus'){const p=D.pathways;plot('pathwayCompare',[{x:p.map(x=>x.score),y:p.map(x=>x.pathway),type:'bar',orientation:'h',text:p.map(x=>x.interpretation),textposition:'outside',hovertemplate:'%{y}<br>Compatibility %{x}/14<br>%{text}<extra></extra>'}],{xaxis:{title:'Ordinal compatibility / 14',range:[0,14]},margin:{l:245,r:35,t:45,b:45}},'<b>How to read</b><p>Higher values mean more criteria were compatible in the Enceladus ordinal matrix. They do not mean higher probability of life.</p>');}else{noData('pathwayCompare','Enceladus-specific pathway matrix',`${x.title} is not scored with the 14-criterion Enceladus matrix. The project does not have an equivalent validated compatibility score for this world.`)}
 const chains={enceladus:[['1 · Observed','H₂ detected in plume material'],['2 · Environmental hypothesis','Water–rock chemistry can provide reducing power; CO₂/carbon chemistry is considered in the metabolic framework'],['3 · Biological analogue','Hydrogenotrophic methanogenesis is compatible with the ThermoBase pathway matrix'],['4 · Competing explanation','Abiotic methane production and transport remain viable alternatives']],europa:[['1 · Observed / constrained','Subsurface ocean and chemically active surface are central mission targets'],['2 · ThermoBase role','Use terrestrial redox/metabolic analogues to organize candidate processes'],['3 · Major unknown','Ocean chemistry, energy flux and surface–ocean exchange remain incompletely constrained'],['4 · Discriminator','Europa Clipper observations can test composition, geology and exchange hypotheses']],trappist:[['1 · Remote observation','Atmospheric spectra constrain possible atmospheric states'],['2 · Biological translation','ThermoBase supplies terrestrial process analogues, not direct planetary measurements'],['3 · Major unknown','Atmospheric composition, surface conditions and stellar/photochemical effects'],['4 · Discriminator','Repeated spectroscopy and stronger retrieval constraints']],k218:[['1 · Remote observation','CH₄ and CO₂ have been reported in JWST observations'],['2 · Biological translation','Terrestrial pathways provide candidate chemical-process analogues'],['3 · Major unknown','Planetary atmosphere/ocean structure and abiotic production pathways'],['4 · Discriminator','Independent atmospheric constraints and stronger abiotic baselines']],earth:[['1 · Known biosphere','Earth is the only world here with independently established life'],['2 · ThermoBase role','Earth supplies the empirical training and validation domain'],['3 · Extrapolation problem','The challenge is transfer beyond the terrestrial domain'],['4 · Discriminator','Independent datasets and planetary analogues test generalization']]};set('enceladusNetwork',chains[w].map((q,i)=>`<div class="reaction-step ${i===3?'caution':''}"><b>${esc(q[0])}</b><span>${esc(q[1])}</span></div>${i<3?'<div class="reaction-arrow">↓</div>':''}`).join(''));renderPlanetaryGrid();}
function renderPlanetaryGrid(){const worlds=worldData();set('planetaryGrid',Object.entries(worlds).map(([k,x])=>`<button class="planet-card ${k===currentWorld?'active':''}" data-world-card="${k}"><span>${esc(x.kind)}</span><strong>${esc(x.title)}</strong><small>${esc(x.score)}</small><p>${esc(x.stance)}</p></button>`).join(''));$$('[data-world-card]').forEach(b=>b.onclick=()=>{$$('#worldTabs button').forEach(x=>x.classList.toggle('active',x.dataset.world===b.dataset.worldCard));currentWorld=b.dataset.worldCard;renderWorld(currentWorld)})}
function renderSynthesis(){set('synthesisDynamic',`<div class="synthesis-grid"><div><b>DATA</b><strong>${D.meta.records.toLocaleString()}</strong><span>organisms</span></div><div><b>FIELDS</b><strong>${D.meta.columns}</strong><span>structured variables</span></div><div><b>THERMAL QC</b><strong>${D.completeness.thermal_complete}</strong><span>complete envelopes</span></div><div><b>PH QC</b><strong>${D.completeness.ph_complete}</strong><span>complete envelopes</span></div></div>`)}
function renderView(v){({overview:renderOverview,physiology:renderPhys,environment:renderEnvironment,metabolism:renderMetabolism,evidence:renderEvidence,analysis:renderAnalysis,ml:renderML,sandbox:renderSandbox,worlds:()=>renderWorld(currentWorld),synthesis:renderSynthesis})[v]?.();setTimeout(enrichCards,250)}
function updateChatContext(){const n=filtered().length;set('chatContext',`Context: ${$('.nav.active')?.textContent?.replace(/^\s*\d+\s*/,'').trim()||'Dataset'} · ${n.toLocaleString()} active records`)}
function openChat(){const c=$('#researchChat');c.classList.add('open');document.body.classList.add('chat-open');c.setAttribute('aria-hidden','false');$('#chatFab').style.display='none';$('#chatQuestion').focus()}
function closeChat(){const c=$('#researchChat');c.classList.remove('open');document.body.classList.remove('chat-open');c.setAttribute('aria-hidden','true');$('#chatFab').style.display=''}
function addChat(role,text){const b=$('#chatBody'),d=document.createElement('div');d.className='chat-msg '+role;d.innerHTML=`<b>${role==='user'?'You':'ThermoBase'}</b><p>${text}</p>`;b.appendChild(d);b.scrollTop=b.scrollHeight}
function chatVisual(){openChat();const a=filtered().filter(r=>num(r.avg_optimum_temp_c)!=null&&num(r.avg_optimum_ph)!=null);const box=$('#chatVisual');box.innerHTML='<div id="chatPlot" class="plot"></div>';if(!a.length){box.innerHTML='<div class="empty-state"><b>No temperature × pH points under the current filters.</b></div>';return}plot('chatPlot',[{x:a.map(r=>r.avg_optimum_temp_c),y:a.map(r=>r.avg_optimum_ph),mode:'markers',type:'scattergl',text:a.map(r=>r.name),hovertemplate:'<b>%{text}</b><br>Topt %{x}°C · pHopt %{y}<extra></extra>'}],{xaxis:{title:'Topt °C'},yaxis:{title:'pHopt'}},'<b>How to read</b><p>Each point is a measured ThermoBase record under the current filters.</p>')}
function chatAnswer(q){
 const l=q.toLowerCase(),a=filtered();
 if(/what is thermobase|what is the dataset|describe the dataset/.test(l))return `ThermoBase is a curated research release of <strong>${D.meta.records.toLocaleString()}</strong> organism records with <strong>${D.meta.columns}</strong> structured fields spanning identity, physiology, environment, metabolism, chemistry, evidence and derived analysis. The web layer exposes the full field set so individual variables can be inspected rather than reduced to summary charts.`;
 if(/thermal|topt/.test(l)&&/complete|missing|coverage/.test(l))return `There are <strong>${D.completeness.thermal_complete}</strong> complete thermal envelopes out of ${D.meta.records}. Tmin, Topt and Tmax ordering has no current QC violations.`;
 if(/p.?h/.test(l)&&/complete|missing|coverage/.test(l))return `There are <strong>${D.completeness.ph_complete}</strong> complete pH envelopes. The pH layer is substantially sparser than temperature, so pH-dependent analyses are measured-subset analyses.`;
 if(/hydrogen oxidation|h2 oxidation/.test(l)&&/lineage|group|taxonomy|phylum|control|stress/.test(l)){const r=D.ml_random.find(x=>x.pathway==='Hydrogen oxidation'),g=D.ml_grouped_validation_v74?.find(x=>x.pathway==='hydrogen_oxidation')||D.ml_grouped.find(x=>x.pathway==='Hydrogen oxidation');const gv=g?.grouped_ROC_AUC??g?.roc;return `Hydrogen oxidation has random environment ROC-AUC <strong>${r.environment.toFixed(3)}</strong>, but phylum-grouped environment ROC-AUC <strong>${gv==null?'not estimable':Number(gv).toFixed(3)}</strong>. The project interpretation is that the random-CV signal collapses under lineage control.`}
 if(/14.?\s*\/\s*14|probability.*life|chance.*life|enceladus/.test(l))return `The Enceladus hydrogenotrophic methanogenesis score is <strong>14/14</strong>. That is an <strong>ordinal compatibility score across 14 criteria</strong>, not a probability of life. Abiotic methane and incomplete planetary constraints remain major alternatives.`;
 if(/337|field architecture|schema|fields/.test(l)){const groups=new Set(D.schema_fields.map(x=>x.group));return `ThermoBase contains <strong>${D.meta.columns} structured fields</strong> across <strong>${groups.size} actual field families</strong> in the web release. The evidence explorer can search field names and representative field values, then expose coverage and examples.`}
 if(/methanogenesis/.test(l)&&/model|ml|predict|auc|score/.test(l)){const r=modelRow('methanogenesis','environment_only');return `Methanogenesis environment-only random ROC-AUC is <strong>${r.ROC_AUC.toFixed(3)}</strong>. Phylum-grouped validation is <strong>not estimable</strong> because all positives are concentrated in one phylum group; it should not be called lineage-independent prediction.`}
 if(/sulfate reduction/.test(l)&&/model|ml|predict|auc|score/.test(l)){const r=modelRow('sulfate reduction','environment_only'),g=D.ml_grouped_validation_v74?.find(x=>x.pathway==='sulfate_reduction')||D.ml_grouped.find(x=>x.pathway==='Sulfate reduction');const gv=g?.grouped_ROC_AUC??g?.roc;return `Sulfate reduction environment-only ROC-AUC is <strong>${r.ROC_AUC.toFixed(3)}</strong> in random CV and <strong>${Number(gv).toFixed(3)}</strong> under phylum grouping. Useful environmental signal persists, although performance is lower under the stricter test.`}
 if(/compare/.test(l)&&/methanogenesis|sulfate reduction|sulfur reduction|iron reduction|fermentation|hydrogen oxidation/.test(l)){const ps=['Methanogenesis','Sulfate reduction','Sulfur reduction','Iron reduction','Fermentation','Hydrogen oxidation'].filter(p=>l.includes(p.toLowerCase()));if(ps.length>=2){return ps.map(p=>{const e=modelRow(p,'environment_only'),t=modelRow(p,'taxonomy_only'),c=modelRow(p,'environment_plus_taxonomy');return `<strong>${esc(p)}</strong>: environment ${Number(e?.ROC_AUC).toFixed(3)}, taxonomy ${Number(t?.ROC_AUC).toFixed(3)}, combined ${Number(c?.ROC_AUC).toFixed(3)} ROC-AUC.`}).join('<br>')}}
 if(/how many|count|number of/.test(l)){const term=l.match(/methanogenesis|sulfate|sulfur|iron|hydrogen|methane|h2|co2|carbon dioxide|fermentation|hydrothermal|aquatic|terrestrial|anaerob|aerob/);if(term){const t=term[0].replace('h2','molecular_hydrogen').replace('co2','carbon_dioxide');const hits=D.records.filter(r=>[r.name,r.environment,r.ecosystem,r.metabolism_pathways,r.extracted_compounds,r.predicted_biosignature_species].some(v=>String(v||'').toLowerCase().includes(t))).length;return `<strong>${hits}</strong> records in the current ThermoBase release match <b>${esc(term[0])}</b> across organism, environment, metabolism, compound and biosignature fields. This is a text-layer count, not a pathway prevalence estimate.`}}
 if(/median|average|mean|range/.test(l)&&/temperature|topt|p.?h|salinity|pressure/.test(l)){const field=/p.?h/.test(l)?'avg_optimum_ph':/salinity/.test(l)?'avg_opt_salinity_percent_normalized_v40':/pressure/.test(l)?'optimum_pressure_mpa':'avg_optimum_temp_c';const vals=a.map(r=>num(r[field])).filter(v=>v!=null);if(vals.length){const sorted=vals.slice().sort((x,y)=>x-y);const med=sorted[Math.floor(sorted.length/2)];return `${field==='avg_optimum_temp_c'?'Optimum temperature':field==='avg_optimum_ph'?'Optimum pH':field==='avg_opt_salinity_percent_normalized_v40'?'Normalized optimum salinity':'Optimum pressure'}: <strong>${fmt(med,2)}</strong> median across <strong>${vals.length}</strong> measured active records; range ${fmt(sorted[0],2)}–${fmt(sorted.at(-1),2)}.`}}
 if(/what is|tell me about|explain/.test(l)){const nameHit=D.records.find(r=>l.includes(String(r.name||'').toLowerCase())&&String(r.name||'').length>5);if(nameHit)return `I found <strong>${esc(nameHit.name)}</strong>: domain ${esc(nameHit.domain||'—')}, phylum ${esc(nameHit.phylum||'—')}, environment ${esc(nameHit.environment||'—')}, Topt ${nameHit.avg_optimum_temp_c??'—'} °C, pHopt ${nameHit.avg_optimum_ph??'—'}, pathways ${esc(nameHit.metabolism_pathways||'—')}. Click the record result or ask about its chemistry/QC for more detail.`;const fieldHit=fieldCache.find(f=>l.includes(f.name.toLowerCase()));if(fieldHit){showField(fieldHit);return `I opened the field detail for <strong>${esc(fieldHit.name)}</strong>, including population, missingness, examples and origin class.`}}
 if(/search|find/.test(l)){const term=l.match(/methane|hydrogen|h2|sulfate|sulfur|iron|co2|carbon dioxide|acetate|nitrate|fermentation|hydrothermal/);if(term){const t=term[0];const hits=D.records.filter(r=>Object.values(r).some(v=>String(v??'').toLowerCase().includes(t))).slice(0,20);return `<strong>${hits.length}</strong> matching records for <b>${esc(t)}</b>: ${hits.map(r=>`<br>• <button class="chat-record" data-record="${r.record_id}">${esc(r.name)}</button> — ${esc(r.environment||'—')} — ${esc(r.metabolism_pathways||'—')}`).join('')||'<br>No matching record.'}`}}
 if(/show|plot|visual|chart|graph/.test(l)&&/temperature|physiolog|topt|p.?h/.test(l)){chatVisual();return 'I generated a temperature × pH visualization using the current active filters.'}
 if(/environment|where.*from|ecosystem/.test(l)&&/how many|which|what/.test(l)){const c=Object.entries(countBy(a,'environment')).sort((x,y)=>y[1]-x[1]).slice(0,8);return `The most represented active environments are: ${c.map(x=>`<strong>${esc(x[0])}</strong> (${x[1]})`).join(', ')}.`}
 return `I can search the 1,238-record research layer, inspect fields and organisms, report stored QC/ML results, compare metabolic pathways, and generate a temperature × pH visual. Try a question containing an organism name, field, pathway, chemical, metric, environment or planetary case. Unsupported claims are not invented.`}

function submitChat(q){if(!q.trim())return;addChat('user',esc(q));addChat('assistant',chatAnswer(q.trim()))}
function showRecord(id){const r=D.records.find(x=>String(x.record_id)===String(id));if(!r)return;openChat();addChat('assistant',`<strong>${esc(r.name)}</strong><br>Record ${r.record_id}<br>Domain: ${esc(r.domain||'—')} · Phylum: ${esc(r.phylum||'—')}<br>Environment: ${esc(r.environment||'—')}<br>Tmin/Topt/Tmax: ${r.min_temp_c??'—'} / ${r.avg_optimum_temp_c??'—'} / ${r.max_temp_c??'—'} °C<br>pHopt: ${r.avg_optimum_ph??'—'} · Pressure: ${r.optimum_pressure_mpa??'—'} MPa<br>Pathways: ${esc(r.metabolism_pathways||'—')}<br>Compounds: ${esc(r.extracted_compounds||'—')}<br>QC: ${esc(r.final_qc_record_status_v71||'—')}`)}
function bindWorldTabs(){ $$('#worldTabs button').forEach(b=>b.onclick=()=>{$$('#worldTabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentWorld=b.dataset.world;renderWorld(currentWorld)})}
function bind(){
 $$('.nav').forEach(b=>b.onclick=()=>go(b.dataset.view));$$('[data-jump]').forEach(b=>b.onclick=()=>go(b.dataset.jump));
 $('#resetFilters').onclick=()=>{['fDomain','fEnvironment','fTopt','fPh','fMet'].forEach(id=>{const e=$('#'+id);if(e)e.value=''});activeEnv='';renderView($('.view.active').id);updateChatContext()};
 $('#themeToggle').onclick=()=>{const dark=document.documentElement.dataset.theme==='dark';document.documentElement.dataset.theme=dark?'':'dark';localStorage.setItem('tb-theme',dark?'light':'dark');$('#themeToggle').textContent=dark?'Dark mode':'Light mode'};
 $('#sidebarToggle').onclick=()=>{const collapsed=document.documentElement.classList.toggle('sidebar-collapsed');localStorage.setItem('tb-sidebar',collapsed?'collapsed':'open');$('#sidebarToggle').textContent=collapsed?'›':'‹';$('#sidebarToggle').setAttribute('aria-label',collapsed?'Expand navigation':'Collapse navigation')};$('#mobileNavToggle')?.addEventListener('click',()=>document.documentElement.classList.toggle('mobile-nav-open'));$$('.nav').forEach(b=>b.addEventListener('click',()=>document.documentElement.classList.remove('mobile-nav-open')));
 ['fDomain','fEnvironment','fTopt','fPh','fMet'].forEach(id=>$('#'+id)?.addEventListener('input',()=>{renderPhys();renderEnvironment();updateChatContext()}));
 $('#metSearch')?.addEventListener('input',renderMetabolism);$('#clearMet')?.addEventListener('click',()=>{$('#metSearch').value='';renderMetabolism()});
 $('#schemaSearch')?.addEventListener('input',renderSchema);$('#schemaGroup')?.addEventListener('change',renderSchema);$('#schemaOrigin')?.addEventListener('change',renderSchema);
 ['pairX','pairY'].forEach(id=>$('#'+id)?.addEventListener('change',renderPair));['mlPathway','mlPredictors','mlValidation'].forEach(id=>$('#'+id)?.addEventListener('change',renderML));$('#mlThreshold')?.addEventListener('input',renderML);['mlDomain','mlEnvironment','mlOxygen','mlTemp','mlPH','mlSal','mlPressure'].forEach(id=>$('#'+id)?.addEventListener('input',runMLScenario));$('#mlClearScenario')?.addEventListener('click',()=>{['mlDomain','mlEnvironment','mlOxygen','mlTemp','mlPH','mlSal','mlPressure'].forEach(id=>{const e=$('#'+id);if(e)e.value=''});runMLScenario()});
 $('#runSandbox')?.addEventListener('click',runSandbox);['sbTemp','sbPH','sbSal','sbPressure','sbO2','sbH2','sbCO2','sbSulfate','sbSulfur','sbIron'].forEach(id=>$('#'+id)?.addEventListener('change',runSandbox));
 $('#chatFab').onclick=openChat;$('#chatClose').onclick=closeChat;$('#chatForm').onsubmit=e=>{e.preventDefault();const q=$('#chatQuestion').value;$('#chatQuestion').value='';submitChat(q)};$$('[data-chatq]').forEach(b=>b.onclick=()=>submitChat(b.dataset.chatq));
 $('#modalClose').onclick=closeModal;$('#modalBackdrop').onclick=closeModal;document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeChat()}});
 document.addEventListener('click',e=>{const r=e.target.closest('[data-record]');if(r)showRecord(r.dataset.record);const f=e.target.closest('[data-field]');if(f){const m=fieldCache.find(x=>x.name===f.dataset.field);if(m){if(f.closest('#modalDetail'))showFieldModal(m);else showField(m)}}const p=e.target.closest('[data-pathway]');if(p){activePathway=p.dataset.pathway;renderMetabolism()}});
 window.addEventListener('resize',()=>$$('.plot').forEach(el=>{if(el.dataset.plotted==='1')try{Plotly.Plots.resize(el)}catch{}}));
}
window.addEventListener('popstate',()=>{const id=location.hash.slice(1)||'overview';if(D)go(id,{push:false})});
function boot(){bindWorldTabs();fetch('data/thermobase.json').then(r=>r.json()).then(x=>{D=x;buildFieldCache();$('#dataStatus').textContent=`research layer · ${D.meta.records.toLocaleString()} records · ${D.meta.columns} fields`;populateFilters();const saved=localStorage.getItem('tb-theme');if(saved==='dark'){document.documentElement.dataset.theme='dark';$('#themeToggle').textContent='Light mode'}const sb=localStorage.getItem('tb-sidebar');if(sb==='collapsed'){document.documentElement.classList.add('sidebar-collapsed');$('#sidebarToggle').textContent='›'}bind();go(location.hash.slice(1)||'overview')}).catch(e=>{console.error(e);$('#dataStatus').textContent='data load failed'})}
boot();
